int main() {
    int n;
    scanf("%d", &n);
    int d[n];
    for (int i = 0; i < n; i++) {
        scanf("%d", &d[i]);
    }

    int m = n + 1;
    int a[m];
    a[0] = 0;
    for (int i = 0; i < n; i++) {
        a[i+1] = d[i];
    }

    qsort(a, m, sizeof(int), cmp);

    int ans = 0;
    // Try all shifts
    for (int start = 0; start < m; start++) {
        int b[m];
        for (int i = 0; i < m; i++) {
            b[i] = a[(start + i) % m];
        }
        // Make circular by adding 24
        int min_gap = 24;
        for (int i = 0; i < m - 1; i++) {
            int gap = b[i+1] - b[i];
            if (gap < min_gap) min_gap = gap;
        }
        // last to first wrap
        int wrap_gap = (24 - b[m-1]) + b[0];
        if (wrap_gap < min_gap) min_gap = wrap_gap;

        if (min_gap > ans) ans = min_gap;
    }

    printf("%d\n", ans);
    return 0;
}

