#define MAXN 205

int n;
int D[105];
// 2-SAT with 2*(n+1) variables
// person 0 = Takahashi at position 0 (fixed)
// person i (1..n): position D[i] or 24-D[i]

int dist(int a, int b) {
    int d = abs(a - b);
    if (d > 12) d = 24 - d;
    return d;
}

// 2-SAT
int adj[MAXN][MAXN], deg[MAXN];
int radj[MAXN][MAXN], rdeg[MAXN];
int order[MAXN], ocnt;
int comp[MAXN];
int visited[MAXN];

void dfs1(int v, int sz) { visited[v]=1; for(int i=0;i<deg[v];i++){int u=adj[v][i];if(!visited[u])dfs1(u,sz);} order[ocnt++]=v; }
void dfs2(int v, int c) { comp[v]=c; for(int i=0;i<rdeg[v];i++){int u=radj[v][i];if(comp[u]<0)dfs2(u,c);} }

int check(int m) {
    int sz = 2*(n+1);
    memset(deg,0,sizeof(deg)); memset(rdeg,0,sizeof(rdeg));
    // positions: person i has pos[i][0]=D[i], pos[i][1]=24-D[i]; person 0 fixed at 0
    // node 2i = person i choice 0, node 2i+1 = person i choice 1
    int pos[105][2];
    pos[0][0]=pos[0][1]=0;
    for(int i=1;i<=n;i++){pos[i][0]=D[i];pos[i][1]=24-D[i];}
    // add implication: if person 0 choice 0 conflicts with person i choice c, add clause
    // For pair (i,j), choices (a,b): if dist < m, add clause NOT(i=a) OR NOT(j=b)
    // i.e., (i=a) -> NOT(j=b), (j=b) -> NOT(i=a)
    #define ADD(u,v) adj[u][deg[u]++]=v; radj[v][rdeg[v]++]=u;
    for(int i=0;i<=n;i++) for(int j=i+1;j<=n;j++) for(int a=0;a<2;a++) for(int b=0;b<2;b++) {
        if(dist(pos[i][a],pos[j][b])<m) { ADD(2*i+a,2*j+(1-b)); ADD(2*j+b,2*i+(1-a)); }
    }
    // person 0 is fixed at choice 0: force 2*0+0=true, so NOT(2*0+1): add 2*0+1 -> 2*0+0... just add unit: 1->0
    ADD(1,0); // if choice1 then choice0 (contradiction forces choice0)
    ocnt=0; memset(visited,0,sizeof(visited)); memset(comp,-1,sizeof(comp));
    for(int i=0;i<sz;i++) if(!visited[i]) dfs1(i,sz);
    int cc=0; for(int i=ocnt-1;i>=0;i--) if(comp[order[i]]<0) dfs2(order[i],cc++);
    for(int i=0;i<=n;i++) if(comp[2*i]==comp[2*i+1]) return 0;
    return 1;
}

