static int max(int a, int b) { return a > b ? a : b; }

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int cnt[13] = {0}; /* cnt[d] for d = 0..12 */
    cnt[0] = 1;        /* Takahashi is fixed at 0 */

    for (int i = 0; i < N; i++) {
        int d;
        scanf("%d", &d);
        cnt[d]++;
    }

    /* Immediate impossibility checks:
       - more than one person at distance 0 or 12 => same clock position forced
       - for 1..11, more than two people with same D => pigeonhole, collision forced
    */
    if (cnt[0] > 1 || cnt[12] > 1) {
        printf("0\n");
        return 0;
    }
    for (int d = 1; d <= 11; d++) {
        if (cnt[d] > 2) {
            printf("0\n");
            return 0;
        }
    }

    /* For each d in 1..11:
       - if cnt[d] == 0: nothing
       - if cnt[d] == 1: choose either +d or -d(=24-d)
       - if cnt[d] == 2: both positions are forced, d and 24-d
       cnt[12] == 1 means one person at 12.
    */

    int single[11], m = 0;
    int fixed[24], fsz = 0;

    fixed[fsz++] = 0;
    if (cnt[12] == 1) fixed[fsz++] = 12;

    for (int d = 1; d <= 11; d++) {
        if (cnt[d] == 1) {
            single[m++] = d;
        } else if (cnt[d] == 2) {
            fixed[fsz++] = d;
            fixed[fsz++] = 24 - d;
        }
    }

    int ans = 0;
    int total_masks = 1 << m;

    for (int mask = 0; mask < total_masks; mask++) {
        int pos[24];
        int sz = 0;

        for (int i = 0; i < fsz; i++) pos[sz++] = fixed[i];

        for (int i = 0; i < m; i++) {
            int d = single[i];
            if (mask & (1 << i)) pos[sz++] = d;
            else pos[sz++] = 24 - d;
        }

        int best_min = 24;

        for (int i = 0; i < sz; i++) {
            for (int j = i + 1; j < sz; j++) {
                int diff = pos[i] - pos[j];
                if (diff < 0) diff = -diff;
                int gap = diff < 24 - diff ? diff : 24 - diff;
                if (gap < best_min) best_min = gap;
            }
        }

        ans = max(ans, best_min);
    }

    printf("%d\n", ans);
    return 0;
}

