    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int[] times = new int[N + 1];
        times[0] = 0; // Takahashi's time
        for (int i = 1; i <= N; i++) {
            times[i] = sc.nextInt();
        }
        Arrays.sort(times);

        int[] doubled = new int[2 * (N + 1)];
        for (int i = 0; i <= N; i++) {
            doubled[i] = times[i];
            doubled[i + N + 1] = times[i] + 24;
        }

        int low = 0, high = 12;
        while (low < high) {
            int mid = (low + high + 1) / 2;
            if (canPlace(doubled, N + 1, mid)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        System.out.println(low);
    }

    static boolean canPlace(int[] arr, int total, int minGap) {
        // arr is sorted and doubled with +24
        // try to pick 'total' points with at least minGap between consecutive picks
        int count = 1;
        int last = arr[0];
        for (int i = 1; i < arr.length && count < total; i++) {
            if (arr[i] - last >= minGap) {
                count++;
                last = arr[i];
            }
        }
        // check circular condition: first and last in circle
        return count == total && (arr[0] + 24 - last >= minGap);
    }
}

