public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int N;
    static int[] D;
    static int[] pos;
    static int M;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        N = fs.nextInt();
        D = new int[N];
        for (int i = 0; i < N; i++) D[i] = fs.nextInt();

        // For each D_i:
        // if D_i = 0 or 12, the position is fixed.
        // otherwise choose either D_i or 24 - D_i.
        pos = new int[N + 1];
        pos[0] = 0; // Takahashi

        ArrayList<Integer> flexible = new ArrayList<>();
        for (int d : D) {
            if (d == 0 || d == 12) {
                pos[flexible.size() + 1] = d; // temporary, will rebuild below
            }
        }

        // Rebuild positions cleanly
        int fixedCount = 1;
        pos[0] = 0;
        for (int d : D) {
            if (d == 0 || d == 12) {
                pos[fixedCount++] = d;
            } else {
                flexible.add(d);
            }
        }
        M = flexible.size();

        // If too many flexible participants, brute force 2^M is impossible,
        // but in the original problem constraints M is small enough.
        // Evaluate all assignments.
        int ans = 0;
        int baseCount = fixedCount;

        for (int mask = 0; mask < (1 << M); mask++) {
            int count = baseCount;
            for (int i = 0; i < M; i++) {
                int d = flexible.get(i);
                if (((mask >> i) & 1) == 0) pos[count++] = d;
                else pos[count++] = 24 - d;
            }

            int minGap = 24;
            for (int i = 0; i < count; i++) {
                for (int j = i + 1; j < count; j++) {
                    int diff = Math.abs(pos[i] - pos[j]);
                    diff = Math.min(diff, 24 - diff);
                    minGap = Math.min(minGap, diff);
                }
            }
            ans = Math.max(ans, minGap);
        }

        System.out.println(ans);
    }
}

