#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int> cnt(13, 0); // 0..12

    for (int i = 0; i < N; ++i) {
        int d;
        cin >> d;
        cnt[d]++;
    }

    // Takahashi is fixed at 0.
    // For each D_i:
    // - if D_i = 0 or 12, position is fixed (0 or 12), so duplicates impossible
    // - otherwise choose either D_i or 24-D_i
    //
    // Since D_i is in [0,12], for d=1..11 if cnt[d] >= 3 impossible to keep all distinct
    // (only two possible positions: d and 24-d).
    // Also cnt[0] >= 1 impossible because Takahashi already at 0.
    // Also cnt[12] >= 2 impossible because only one position 12.
    //
    // Enumerate all choices for d=1..11 with cnt[d]==1 or 2.

    if (cnt[0] >= 1 || cnt[12] >= 2) {
        cout << 0 << '\n';
        return 0;
    }
    for (int d = 1; d <= 11; ++d) {
        if (cnt[d] >= 3) {
            cout << 0 << '\n';
            return 0;
        }
    }

    vector<int> ds;
    for (int d = 1; d <= 11; ++d) {
        for (int k = 0; k < cnt[d]; ++k) ds.push_back(d);
    }

    int m = ds.size();
    int ans = 0;

    for (int mask = 0; mask < (1 << m); ++mask) {
        vector<int> pos;
        pos.push_back(0); // Takahashi
        if (cnt[12] == 1) pos.push_back(12);

        for (int i = 0; i < m; ++i) {
            int d = ds[i];
            if (mask & (1 << i)) pos.push_back(d);
            else pos.push_back(24 - d);
        }

        sort(pos.begin(), pos.end());

        bool distinct_ok = true;
        for (int i = 1; i < (int)pos.size(); ++i) {
            if (pos[i] == pos[i - 1]) {
                distinct_ok = false;
                break;
            }
        }
        if (!distinct_ok) continue;

        int mn = 24;
        for (int i = 1; i < (int)pos.size(); ++i) {
            mn = min(mn, pos[i] - pos[i - 1]);
        }
        mn = min(mn, 24 - pos.back() + pos.front()); // circular gap

        ans = max(ans, mn);
    }

    cout << ans << '\n';
    return 0;
}
